// src/hash.ts
var normalizeMarkdownLineEndings2 = (markdown) => markdown.replace(/\r\n/g, `
`).replace(/\r/g, `
`).replace(/\s+$/u, "") + `
`;
var sha256Digest = (value4) => `sha256:${sha256Hex(value4)}`;
var stripChildAnchors = (body) => normalizeMarkdownLineEndings2(body.split(`
`).filter((line) => /^\s*<page\b[^>]*>.*<\/page>\s*$/u.test(line) === false).join(`
`).replace(/\n{3,}/gu, `

`).replace(/\n+$/u, `
`));

// src/frontmatter.ts
var frontmatterEndMarker = `
---
`;
var decodeNmdFrontmatterJson = exports_Schema.decodeUnknownEffect(exports_Schema.fromJsonString(NmdFrontmatterV2), {
  errors: "all",
  onExcessProperty: "error"
});
var encodeNmdFrontmatterJsonSync = exports_Schema.encodeSync(exports_Schema.fromJsonString(NmdFrontmatterV2, { space: 2 }));
var renderNmdFile = (opts) => `---
${encodeNmdFrontmatterJsonSync(opts.frontmatter)}
---

${normalizeMarkdownLineEndings2(opts.body)}`;
var parseNmdFile = (opts) => exports_Effect.gen(function* () {
  const parsed = yield* exports_Effect.try({
    try: () => {
      const content3 = opts.content.replace(/\r\n/g, `
`);
      if (content3.startsWith(`---
`) === false) {
        throw new Error("Expected `.nmd` frontmatter to start with `---`");
      }
      const endIndex = content3.indexOf(frontmatterEndMarker, 4);
      if (endIndex === -1) {
        throw new Error("Expected closing `---` frontmatter marker");
      }
      const rawFrontmatter = content3.slice(4, endIndex);
      const body = content3.slice(endIndex + frontmatterEndMarker.length).replace(/^\n/u, "");
      return { rawFrontmatter, body: normalizeMarkdownLineEndings2(body) };
    },
    catch: (cause) => new NmdFrontmatterError({
      path: opts.path,
      cause,
      message: `Failed to parse strict .nmd frontmatter in ${opts.path}`
    })
  });
  const decoded = yield* decodeNmdFrontmatterJson(parsed.rawFrontmatter).pipe(exports_Effect.mapError((cause) => new NmdFrontmatterError({
    path: opts.path,
    cause,
    message: `Failed to parse strict .nmd frontmatter in ${opts.path}`
  })));
  return { frontmatter: decoded, body: parsed.body };
});

